int wifi_mgmt_frame_transmit(struct wiphy *wiphy, struct wireless_dev *wdev, struct cfg80211_mgmt_tx_params *params, u64 *cookie) {
    struct ieee80211_hdr *hdr;
    struct ieee80211_mgmt *mgmt;
    int ret = -EINVAL;
    size_t hdr_len;

    if (params->len < IEEE80211_MIN_HEADER_LEN)
        return -EINVAL;

    mgmt = (struct ieee80211_mgmt *)params->buf;
    hdr = &mgmt->header;
    hdr_len = ieee80211_get_hdr_len(hdr);

    if (params->len < (hdr_len + sizeof(mgmt->u)))
        return -EINVAL;

    switch (mgmt->frame_control & IEEE80211_FCTL_STYPE) {
    case IEEE80211_STYPE_PROBE_RESP:
        ret = process_probe_response(wiphy, wdev, params);
        break;
    case IEEE80211_STYPE_ACTION:
        ret = prepare_and_send_action_frame(wiphy, wdev, params, cookie);
        break;
    default:
        ret = -EOPNOTSUPP;
        break;
    }

    if (ret < 0)
        return ret;

    return 0;
}

int handle_mgmt_tx(struct wiphy *wiphy, struct wireless_dev *wdev,
                   struct cfg80211_mgmt_tx_params *params, u64 *cookie)
{
    int ret = -EINVAL;
    struct ieee80211_mgmt *mgmt;
    u16 fc;

    if (!params->buf || params->len < 24)
        return -EINVAL;

    mgmt = (struct ieee80211_mgmt *)params->buf;
    fc = le16_to_cpu(mgmt->frame_control);

    if (fc & IEEE80211_FCTL_FTYPE_MASK) {
        if (ieee80211_is_probe_resp(fc)) {
            struct ieee80211_probe_resp *probe_resp;

            if (params->len < 24 + 2 + 8)
                return -EINVAL;

            probe_resp = (struct ieee80211_probe_resp *)mgmt->u.probe_resp;
            if (probe_resp->timestamp >= IEEE80211_HT_CAP_INFO_SIZE)
                return -EINVAL;

            mgmt->u.probe_resp.timestamp = cpu_to_le64(jiffies);
            ret = cfg80211_mgmt_tx_status(wiphy, *cookie, mgmt, params->len, true, NULL, GFP_KERNEL);
        } else if (ieee80211_is_action(fc)) {
            mgmt->u.action.category = WLAN_CATEGORY_PUBLIC;
            ret = send_action_frame(wiphy, wdev, mgmt, params->len, cookie);
        }
    }

    return ret;
}

int wifi_mgmt_tx(struct wiphy *wiphy, struct wireless_dev *wdev,
                 struct cfg80211_mgmt_tx_params *params, u64 *cookie)
{
    int ret = -EINVAL;
    struct ieee80211_mgmt *mgmt;

    if (!params || !params->len || params->len < IEEE80211_MIN_HEADER_LEN)
        return ret;

    mgmt = kzalloc(params->len, GFP_KERNEL);
    if (!mgmt)
        return -ENOMEM;

    memcpy(mgmt, params->buf, params->len);

    if (ieee80211_is_probe_resp(mgmt->frame_control)) {
        u32 ie_len = params->len - 24;

        if (ie_len > 0) {
            mgmt->u.probe_resp.variable = kmemdup(params->buf + 24,
                                                  ie_len, GFP_KERNEL);
            if (!mgmt->u.probe_resp.variable) {
                ret = -ENOMEM;
                goto out;
            }
        }
        ret = handle_probe_response(mgmt, ie_len, cookie);
    } else if (ieee80211_is_action(mgmt->frame_control)) {
        mgmt->u.action.category = params->action_category;
        mgmt->u.action.data[0] = params->action_code;
        ret = send_action_frame(mgmt, params->len, cookie);
    } else {
        ret = -EOPNOTSUPP;
    }

out:
    kfree(mgmt);
    return ret;
}

int handle_mgmt_tx(struct wiphy *wiphy, struct wireless_dev *wdev, struct cfg80211_mgmt_tx_params *params, u64 *cookie)
{
    const u8 *frame = params->buf;
    size_t len = params->len;

    if (len < IEEE80211_MIN_HEADER_LEN)
        return -EINVAL;

    if (frame[0] & IEEE80211_FC_TYPE_MASK) {
        if (frame[0] == (IEEE80211_FC0_TYPE_MGMT | IEEE80211_FC0_SUBTYPE_PROBE_RESP)) {
            struct ieee80211_mgmt *mgmt;
            mgmt = kmalloc(len, GFP_KERNEL);
            if (!mgmt)
                return -ENOMEM;

            memcpy(mgmt, frame, len);
            mgmt->u.probe_resp.ie = mgmt->u.probe_resp.variable;
            mgmt->u.probe_resp.ie_len = len - (mgmt->u.probe_resp.variable - (u8 *)mgmt);

            *cookie = (u64)(unsigned long)mgmt;
            return 0;
        } else if (frame[0] == (IEEE80211_FC0_TYPE_MGMT | IEEE80211_FC0_SUBTYPE_ACTION)) {
            struct ieee80211_mgmt action_frame;
            memcpy(&action_frame, frame, len);

            if (len < (sizeof(action_frame) - sizeof(action_frame.u.action)))
                return -EINVAL;

            *cookie = (u64)(unsigned long)(&action_frame);
            return 0;
        }
    }

    return -EINVAL;
}

int wifi_mgmt_frame_transmission(struct wiphy *wiphy, struct wireless_dev *wdev, struct cfg80211_mgmt_tx_params *params, u64 *cookie) {
    int ret = -EINVAL;
    u8 frame_type;

    if (!params || !params->buf || params->len < 24) {
        return -EINVAL;
    }

    frame_type = params->buf[0] & 0x0f;

    if (frame_type == WLAN_FC_TYPE_MGMT) {
        switch (params->buf[1] & 0x0f) {
            case WLAN_FC_SUBTYPE_PROBE_RESP:
                {
                    struct ieee80211_mgmt *mgmt;
                    mgmt = kmalloc(params->len, GFP_KERNEL);
                    if (!mgmt) {
                        return -ENOMEM;
                    }

                    memcpy(mgmt, params->buf, params->len);
                    mgmt->u.probe_resp.variable[0] = 0x01;
                    mgmt->u.probe_resp.variable[1] = 0x08;
                    mgmt->u.probe_resp.variable[2] = 0x0c;

                    *cookie = jiffies_to_msecs(jiffies);
                    ret = send_mgmt_frame(wdev, mgmt, params->len, *cookie);
                    if (ret < 0) {
                        kfree(mgmt);
                    }
                }
                break;
            case WLAN_FC_SUBTYPE_ACTION:
                {
                    struct ieee80211_mgmt *mgmt;
                    mgmt = kmalloc(params->len, GFP_KERNEL);
                    if (!mgmt) {
                        return -ENOMEM;
                    }

                    memcpy(mgmt, params->buf, params->len);
                    mgmt->u.action.category = WLAN_ACTION_PUBLIC;

                    *cookie = jiffies_to_msecs(jiffies);
                    ret = send_mgmt_frame(wdev, mgmt, params->len, *cookie);
                    if (ret < 0) {
                        kfree(mgmt);
                    }
                }
                break;
            default:
                ret = -EINVAL;
                break;
        }
    } else {
        ret = -EINVAL;
    }

    return ret;
}
